import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor list (undirected, no self-loops)
    neighbors = []
    if is_matrix:
        for i in range(n):
            neighbors.append([j for j in range(n) if adj[i][j] == 1])
    else:
        for i in range(n):
            neighbors.append(list(adj[i]))
        # Ensure symmetry
        for u in range(n):
            for v in neighbors[u]:
                if u not in neighbors[v]:
                    neighbors[v].append(u)

    # Trivial cases: edgeless or complete graph
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    is_complete = True
    for i in range(n):
        if len(neighbors[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))

    # DSATUR with efficient data structures
    color = [-1] * n
    neighbor_colors = [set() for _ in range(n)]
    saturation = [0] * n
    uncolored = set(range(n))

    # Start with vertex of highest degree
    v = max(uncolored, key=lambda x: len(neighbors[x]))
    color[v] = 0
    uncolored.remove(v)
    for u in neighbors[v]:
        if color[u] == -1:
            if 0 not in neighbor_colors[u]:
                neighbor_colors[u].add(0)
                saturation[u] += 1

    # Main DSATUR loop
    while uncolored:
        # Select vertex: max saturation, then max degree in uncolored subgraph, then random
        best_v = -1
        best_sat = -1
        best_deg = -1
        for v in uncolored:
            sat_v = saturation[v]
            deg_v = sum(1 for u in neighbors[v] if u in uncolored)
            if sat_v > best_sat or (sat_v == best_sat and deg_v > best_deg) or \
               (sat_v == best_sat and deg_v == best_deg and random.random() < 0.5):
                best_sat = sat_v
                best_deg = deg_v
                best_v = v
        v = best_v

        # Assign smallest available color (MEX)
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c
        uncolored.remove(v)

        # Update saturation and neighbor colors for uncolored neighbors
        for u in neighbors[v]:
            if color[u] == -1:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1

    # Kempe chain refinement to reduce color count
    max_color = max(color) if n > 0 else -1
    if max_color <= 0:
        return color

    # Precompute neighbor sets for O(1) adjacency checks
    neighbor_sets = [set(neighbors[i]) for i in range(n)]

    improved = True
    while improved and max_color > 0:
        improved = False
        target_color = max_color
        vk = [i for i in range(n) if color[i] == target_color]
        if not vk:
            max_color -= 1
            continue

        for v in vk[:]:  # iterate over a copy
            # Try direct reassignment to a lower color
            for c in range(target_color):
                # Check if any neighbor has color c
                if not any(color[u] == c for u in neighbors[v]):
                    color[v] = c
                    improved = True
                    break
            if color[v] != target_color:
                continue  # successfully reassigned

            # Try Kempe chain swap for each lower color c
            for c in range(target_color):
                # Build Kempe chain component of v for colors (target_color, c)
                stack = [v]
                visited = set([v])
                component = [v]
                while stack:
                    node = stack.pop()
                    for u in neighbors[node]:
                        if u not in visited and (color[u] == target_color or color[u] == c):
                            visited.add(u)
                            stack.append(u)
                            component.append(u)

                # Check if swapping is safe: after swap, v becomes c, so no neighbor of v should be c
                # A neighbor u of v will be c after swap if:
                #   - u in component and was target_color -> becomes c
                #   - u not in component and was c -> remains c
                has_c_in_component = False  # neighbor in component that is target_color (would become c)
                has_c_outside = False       # neighbor not in component that is c (remains c)
                for u in neighbors[v]:
                    if color[u] == target_color and u in visited:
                        has_c_in_component = True
                    elif color[u] == c and u not in visited:
                        has_c_outside = True
                    if has_c_in_component or has_c_outside:
                        break
                if not (has_c_in_component or has_c_outside):
                    # Perform swap: target_color <-> c in component
                    for node in component:
                        if color[node] == target_color:
                            color[node] = c
                        elif color[node] == c:
                            color[node] = target_color
                    improved = True
                    break  # break c-loop, move to next v
            if color[v] != target_color:
                break  # successfully recolored via Kempe, move to next v

        # After processing all vk, check if target_color class is eliminated
        if any(color[i] == target_color for i in range(n)):
            max_color -= 1  # could not eliminate, try next lower
        else:
            max_color -= 1  # eliminated, move to next lower

    return color
